 23→/// Adds the send info to a view with the correct layout.
 24→private struct TimelineItemSendInfoModifier: ViewModifier {
 25→    let sendInfo: TimelineItemSendInfo
 26→    let context: TimelineViewModel.Context
 27→    
 28→    var layout: AnyLayout {
 29→        switch sendInfo.layoutType {
 30→        case .horizontal(let spacing):
 31→            AnyLayout(HStackLayout(alignment: .bottom, spacing: spacing))
 32→        case .vertical(let spacing):
 33→            AnyLayout(GridLayout(alignment: .leading, verticalSpacing: spacing))
 34→        case .overlay:
 35→            AnyLayout(ZStackLayout(alignment: .bottomTrailing))
 36→        }
 37→    }
 38→    
 39→    func body(content: Content) -> some View {
 40→        layout {
 41→            content
 42→            
 43→            TimelineItemSendInfoLabel(sendInfo: sendInfo)
 44→                .contentShape(.rect)
 45→                // Tap gesture to avoid the message being detected as a button by VoiceOver
 46→                // (and the action shows a description that is already read to the user).
 47→                .onTapGesture {
 48→                    guard sendInfo.status != nil else { return }
 49→                    context.send(viewAction: .itemSendInfoTapped(itemID: sendInfo.itemID))
 50→                }
 51→        }
 52→    }
 53→}
