 55→/// The label shown for a timeline item with info about it's timestamp and various other indicators.
 56→private struct TimelineItemSendInfoLabel: View {
 57→    let sendInfo: TimelineItemSendInfo
 58→    
 59→    var statusIcon: KeyPath<CompoundIcons, Image>? {
 60→        switch sendInfo.status {
 61→        case .sendingFailed: \.errorSolid
 62→        case .encryptionAuthenticity(let authenticity): authenticity.icon
 63→        case .none: nil
 64→        }
 65→    }
 66→    
 67→    var statusIconAccessibilityLabel: String? {
 68→        switch sendInfo.status {
 69→        case .sendingFailed: L10n.commonSendingFailed
 70→        case .encryptionAuthenticity(let authenticity): authenticity.message
 71→        case .none: nil
 72→        }
 73→    }
 74→    
 75→    var body: some View {
 76→        switch sendInfo.layoutType {
 77→        case .overlay(capsuleStyle: true):
 78→            content
 79→                .padding(.horizontal, 4)
 80→                .padding(.vertical, 2)
 81→                .background(Color.compound.bgSubtleSecondary)
 82→                .cornerRadius(10)
 83→                .padding(.trailing, 4)
 84→                .padding(.bottom, 4)
 85→        case .horizontal, .overlay(capsuleStyle: false):
 86→            content
 87→                .padding(.bottom, -4)
 88→        case .vertical:
 89→            GridRow {
 90→                content
 91→                    .gridColumnAlignment(.trailing)
 92→            }
 93→        }
 94→    }
 95→    
 96→    @ViewBuilder
 97→    var content: some View {
 98→        HStack(spacing: 4) {
 99→            Text(sendInfo.localizedString)
100→            
101→            if let statusIcon {
102→                CompoundIcon(statusIcon, size: .xSmall, relativeTo: .compound.bodyXS)
103→                    .accessibilityLabel(statusIconAccessibilityLabel ?? "")
104→                    .accessibilityHidden(statusIconAccessibilityLabel == nil)
105→            }
106→        }
107→        .font(.compound.bodyXS)
108→        .foregroundStyle(sendInfo.foregroundStyle)
109→    }
110→}
