112→/// All the data needed to render a timeline item's send info label.
113→private struct TimelineItemSendInfo {
114→    enum Status { case sendingFailed, encryptionAuthenticity(EncryptionAuthenticity) }
115→    
116→    /// Describes how the content and the send info should be arranged inside a bubble
117→    enum LayoutType {
118→        case horizontal(spacing: CGFloat = 4)
119→        case vertical(spacing: CGFloat = 4)
120→        case overlay(capsuleStyle: Bool)
121→    }
122→    
123→    let itemID: TimelineItemIdentifier
124→    let localizedString: String
125→    var status: Status?
126→    let layoutType: LayoutType
127→    
128→    var foregroundStyle: Color {
129→        switch status {
130→        case .sendingFailed:
131→            .compound.textCriticalPrimary
132→        case .encryptionAuthenticity(let authenticity):
133→            authenticity.foregroundStyle
134→        case .none:
135→            .compound.textSecondary
136→        }
137→    }
138→}
139→
140→private extension TimelineItemSendInfo {
141→    init(timelineItem: EventBasedTimelineItemProtocol, adjustedDeliveryStatus: TimelineItemDeliveryStatus?) {
142→        itemID = timelineItem.id
143→        localizedString = timelineItem.localizedSendInfo
144→        
145→        status = if case .sendingFailed = adjustedDeliveryStatus {
146→            .sendingFailed
147→        } else if let authenticity = timelineItem.properties.encryptionAuthenticity {
148→            .encryptionAuthenticity(authenticity)
149→        } else {
150→            nil
151→        }
152→        
153→        layoutType = switch timelineItem {
154→        case is TextBasedRoomTimelineItem:
155→            .overlay(capsuleStyle: false)
156→        case let message as EventBasedMessageTimelineItemProtocol:
157→            switch message {
158→            case is ImageRoomTimelineItem, is VideoRoomTimelineItem:
159→                .overlay(capsuleStyle: !message.hasMediaCaption)
160→            case is AudioRoomTimelineItem, is FileRoomTimelineItem:
161→                // swiftlint:disable:next void_function_in_ternary
162→                message.hasMediaCaption ? .overlay(capsuleStyle: false) : .horizontal(spacing: 0) // No spacing as the content already contains it.
163→            case let locationTimelineItem as LocationRoomTimelineItem:
164→                .overlay(capsuleStyle: locationTimelineItem.content.geoURI != nil)
165→            default:
166→                .horizontal()
167→            }
168→        case is StickerRoomTimelineItem:
169→            .overlay(capsuleStyle: true)
170→        case is PollRoomTimelineItem:
171→            .vertical(spacing: 16)
172→        default:
173→            .horizontal()
174→        }
175→    }
176→}
177→
178→private extension EncryptionAuthenticity {
179→    var foregroundStyle: SwiftUI.Color {
180→        switch color {
181→        case .red: .compound.textCriticalPrimary
182→        case .gray: .compound.textSecondary
183→        }
184→    }
185→}
