 12→protocol EventBasedTimelineItemProtocol: RoomTimelineItemProtocol, CustomStringConvertible {
 13→    var timestamp: Date { get }
 14→    var isOutgoing: Bool { get }
 15→    var isEditable: Bool { get }
 16→    var canBeRepliedTo: Bool { get }
 17→    
 18→    var sender: TimelineItemSender { get }
 19→    
 20→    var body: String { get }
 21→    
 22→    var properties: RoomTimelineItemProperties { get }
 23→}
 24→
 25→extension EventBasedTimelineItemProtocol {
 26→    var description: String {
 27→        "\(String(describing: Self.self)): id: \(id), timestamp: \(timestamp), isOutgoing: \(isOutgoing), properties: \(properties)"
 28→    }
 29→
 30→    var isForwardable: Bool {
 31→        isRemoteMessage && !(self is PollRoomTimelineItem)
 32→    }
 33→
 34→    var isRemoteMessage: Bool {
 35→        id.eventID != nil
 36→    }
 37→    
 38→    var isRedacted: Bool {
 39→        self is RedactedRoomTimelineItem
 40→    }
 41→    
 42→    var pollIfAvailable: Poll? {
 43→        (self as? PollRoomTimelineItem)?.poll
 44→    }
 45→    
 46→    var hasStatusIcon: Bool {
 47→        hasFailedToSend || properties.encryptionAuthenticity != nil
 48→    }
 49→    
 50→    var hasFailedToSend: Bool {
 51→        properties.deliveryStatus?.isSendingFailed == true
 52→    }
 53→
 54→    var hasFailedDecryption: Bool {
 55→        self is EncryptedRoomTimelineItem
 56→    }
 57→
 58→    var timelineMenuDescription: String {
 59→        switch self {
 60→        case is VoiceMessageRoomTimelineItem:
 61→            return L10n.commonVoiceMessage
 62→        default:
 63→            return body.trimmingCharacters(in: .whitespacesAndNewlines)
 64→        }
 65→    }
 66→
 67→    func additionalWhitespaces() -> Int {
 68→        var whiteSpaces = 1
 69→        localizedSendInfo.forEach { _ in
 70→            whiteSpaces += 1
 71→        }
 72→
 73→        // To account for the extra spacing created by the status icon
 74→        if hasStatusIcon {
 75→            whiteSpaces += 3
 76→        }
 77→
 78→        return whiteSpaces
 79→    }
 80→
 81→    /// contains the timestamp and an optional edited localised prefix
 82→    /// example: (edited) 12:17 PM
 83→    var localizedSendInfo: String {
 84→        var start = ""
 85→        if properties.isEdited {
 86→            start = "\(L10n.commonEditedSuffix) "
 87→        }
 88→        return start + timestamp.formattedTime()
 89→    }
 90→
 91→    var isCopyable: Bool {
 92→        guard let messageBasedItem = self as? EventBasedMessageTimelineItemProtocol else {
 93→            return false
 94→        }
 95→
 96→        switch messageBasedItem.contentType {
 97→        case .audio, .file, .image, .video, .location, .voice:
 98→            return false
 99→        case .text, .emote, .notice:
100→            return true
101→        }
102→    }
103→    
104→    var supportsMediaCaption: Bool {
105→        guard let messageBasedItem = self as? EventBasedMessageTimelineItemProtocol else { return false }
106→        return messageBasedItem.supportsMediaCaption
107→    }
108→    
109→    var hasMediaCaption: Bool {
110→        guard let messageBasedItem = self as? EventBasedMessageTimelineItemProtocol else { return false }
111→        return messageBasedItem.hasMediaCaption
112→    }
113→}
