12→struct TimelineItemStatusView: View {
13→    let timelineItem: EventBasedTimelineItemProtocol
14→    let adjustedDeliveryStatus: TimelineItemDeliveryStatus?
15→    @EnvironmentObject private var context: TimelineViewModel.Context
16→
17→    private var isLastOutgoingMessage: Bool {
18→        timelineItem.isOutgoing && context.viewState.timelineState.uniqueIDs.last == timelineItem.id.uniqueID
19→    }
20→
21→    var body: some View {
22→        mainContent
23→    }
24→
25→    @ViewBuilder
26→    private var mainContent: some View {
27→        if context.viewState.timelineKind == .pinned {
28→            // Do not display any status when is a pinned events timeline
29→            EmptyView()
30→        } else if context.viewState.showReadReceipts, !timelineItem.properties.orderedReadReceipts.isEmpty {
31→            readReceipts
32→        } else {
33→            deliveryStatusBadge
34→        }
35→    }
36→
37→    @ViewBuilder
38→    var deliveryStatusBadge: some View {
39→        switch adjustedDeliveryStatus {
40→        case .sending:
41→            TimelineDeliveryStatusView(deliveryStatus: .sending)
42→        case .sent, .none:
43→            if isLastOutgoingMessage {
44→                // We only display the sent icon for the latest outgoing message
45→                TimelineDeliveryStatusView(deliveryStatus: .sent)
46→            }
47→        case .sendingFailed:
48→            // Bubbles handle the case internally
49→            EmptyView()
50→        }
51→    }
52→
53→    var readReceipts: some View {
54→        TimelineReadReceiptsView(timelineItem: timelineItem)
55→            .environmentObject(context)
56→    }
57→}
